import manifest from '../../data/images.generated.json'

type Entry = { widths: number[]; width: number; height: number }
const images = manifest as Record<string, Entry>

type Props = {
  /** File name in public/assets without the width suffix, e.g. "hero-modern-residence". */
  name: string
  alt: string
  /** Responsive `sizes` attribute describing the rendered width. */
  sizes: string
  className?: string
  /** Above-the-fold image: eager + high fetch priority. Everything else lazy-loads. */
  priority?: boolean
}

/** Responsive WebP image generated by `npm run images` (see scripts/optimize-images.mjs). */
export function Img({ name, alt, sizes, className, priority = false }: Props) {
  const entry = images[name]
  if (!entry) {
    if (import.meta.env.DEV) console.warn(`[Img] "${name}" is not in images.generated.json — run npm run images`)
    return null
  }
  const srcSet = entry.widths.map((w) => `/assets/${name}-${w}.webp ${w}w`).join(', ')
  const fallback = entry.widths[Math.min(1, entry.widths.length - 1)]
  return (
    <img
      src={`/assets/${name}-${fallback}.webp`}
      srcSet={srcSet}
      sizes={sizes}
      alt={alt}
      width={entry.width}
      height={entry.height}
      loading={priority ? 'eager' : 'lazy'}
      decoding={priority ? 'auto' : 'async'}
      fetchPriority={priority ? 'high' : undefined}
      className={className}
    />
  )
}
